import app from 'flarum/forum/app';
import { extend, override } from 'flarum/common/extend';
import HeaderPrimary from 'flarum/forum/components/HeaderPrimary';
import HeaderSecondary from 'flarum/forum/components/HeaderSecondary';
import IndexSidebar from 'flarum/forum/components/IndexSidebar';
import Footer from 'flarum/forum/components/Footer';
import Navigation from 'flarum/common/components/Navigation';
import GlobalSearch from 'flarum/forum/components/GlobalSearch';
import Button from 'flarum/common/components/Button';
import LinkButton from 'flarum/common/components/LinkButton';
import extractText from 'flarum/common/utils/extractText';
import Strip from './components/Strip';
import Brand from './components/Brand';
import MastheadFooter from './components/MastheadFooter';
import { canStart, startDiscussion } from './components/compose';
import { has, isPhone, t } from './util';

/** The keys HeaderSecondary keeps on the masthead row; the rest go to the strip. */
const ROW = ['search', 'mastheadCompose'];

/*
 * The pinned header (computers and tablets; less/shell/header.less). The
 * whole header, strip included, is fixed at the top, and .App's padding holds
 * its place. Once the page has scrolled by the difference between the full
 * bar and the compact one, html.mh-pinned shrinks the bar; the header is
 * fixed throughout, so nothing below it moves. `position: sticky` never
 * sticks inside Flarum's page, and an IntersectionObserver on a marker at the
 * top of the document does the watching instead of a scroll listener.
 */
function pin() {
  const root = document.documentElement;
  const marker = document.createElement('div');
  marker.className = 'MastheadPinMarker';
  marker.setAttribute('aria-hidden', 'true');
  document.body.appendChild(marker);
  root.classList.add('mh-pin');
  new IntersectionObserver(([entry]) => root.classList.toggle('mh-pinned', !entry.isIntersecting)).observe(marker);
}
export default function header() {
  /*
   * The strip and the title block are mounted once, next to core's own
   * header mounts. The strip's node is created here: core's template has no
   * slot above the header, and adding one server-side would need a view of
   * Masthead's own that every core update could drift from.
   */
  extend(app, 'mount', () => {
    const headerEl = document.getElementById('header');
    const titleEl = headerEl?.querySelector('.Header-title');
    if (headerEl && !document.getElementById('masthead-strip')) {
      const strip = document.createElement('div');
      strip.id = 'masthead-strip';
      headerEl.insertBefore(strip, headerEl.firstChild);
      m.mount(strip, Strip);
    }
    if (titleEl) m.mount(titleEl, Brand);
    if (app.forum.attribute('mastheadPinHeader') !== false) pin();
  });
  extend(HeaderSecondary.prototype, 'items', function (items) {
    if (isPhone()) return;
    if (this.attrs.strip) {
      ROW.forEach(key => items.has(key) && items.remove(key));
      return;
    }
    items.toArray().forEach(item => {
      if (!ROW.includes(item.itemName)) items.remove(item.itemName);
    });
    if (canStart()) {
      items.add('mastheadCompose', m(Button, {
        className: "Button Button--primary MastheadCompose",
        icon: "fas fa-pen",
        onclick: startDiscussion
      }, t('compose')), -10);
    }
  });

  /*
   * The main navigation, when ernestdefoe/header-nav is not installed.
   *
   * Header Nav owns HeaderPrimary when it is there — its editor decides what
   * goes in the header, and drawing Masthead's own links beside its would put
   * everything there twice. Without it, the header carries Home and the
   * forum's own nav links (All Discussions, Tags, whatever extensions add),
   * read from the sidebar's list so they match it exactly.
   */
  extend(HeaderPrimary.prototype, 'items', function (items) {
    if (has('ernestdefoe-header-nav') || isPhone()) return;
    items.add('mastheadHome', m(LinkButton, {
      className: "Button Button--link MastheadNav-link",
      href: app.forum.attribute('basePath') + '/',
      icon: "fas fa-house"
    }, t('nav.home')), 100);
    let nav = [];
    try {
      const sidebar = Object.create(IndexSidebar.prototype);
      sidebar.attrs = {};
      nav = IndexSidebar.prototype.navItems.call(sidebar).toArray();
    } catch (e) {
      // A nav extension that cannot be called outside its page must not take
      // the header with it.
    }
    nav.filter(v => v?.itemName && typeof v.attrs?.href === 'string' && !/^(separator|moreTags|tag\d+)$/.test(v.itemName))
    // Home already covers the front page.
    .filter(v => v.attrs.href !== app.forum.attribute('basePath') + '/').forEach((v, i) => {
      items.add('masthead-' + v.itemName, m(LinkButton, {
        className: "Button Button--link MastheadNav-link",
        href: v.attrs.href,
        icon: v.attrs.icon
      }, extractText(v.children) || v.itemName), 90 - i);
    });
  });

  /*
   * The phone's top bar, on every page: the drawer button, the brand, then
   * search. Where a page puts its own title in the middle of the bar (a
   * discussion's scrubber) or its own action on the right, those take the
   * place of the brand or of search — in CSS (phone.less), from what is
   * actually on the page, so a page Masthead has never heard of (a Page
   * Builder home page, an extension's own page) still gets a bar that says
   * whose forum this is.
   */
  extend(Navigation.prototype, 'items', function (items) {
    if (!isPhone() || !this.attrs.drawer) return;
    items.add('mastheadBrand', m("div", {
      className: "MastheadNav-brand"
    }, m(Brand, null)), 85);
    items.add('mastheadSearch', m("div", {
      className: "MastheadNav-search"
    }, m(GlobalSearch, {
      state: app.search.state
    })), -100);
  });

  // An override that keeps the original: core's footer is empty, but an
  // extension may have put something in it, and that stays above Masthead's.
  override(Footer.prototype, 'view', function (original) {
    return [original(), m(MastheadFooter, null)];
  });
}