import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Link from 'flarum/common/components/Link';
import { t } from '../util';
function kickoff(game) {
  if (game.status === 'in_progress') return m("span", {
    className: "MastheadGame-live"
  }, t('games.live'));
  if (!game.at) return null;

  // dayjs carries the forum's locale: "Sat 3:30 PM", "sam. 15:30".
  return dayjs(game.at).format('ddd LT');
}

/**
 * The next pick'em games, from ernestdefoe/picks. Drawn only when Picks is
 * enabled; the data comes with the portal payload, so it costs no request.
 */
export default class Games extends Component {
  view() {
    const {
      games
    } = this.attrs;
    return m("section", {
      className: "MastheadWidget MastheadWidget--banded MastheadGames",
      "aria-labelledby": "masthead-games"
    }, m("h2", {
      id: "masthead-games",
      className: "MastheadWidget-title"
    }, t('games.title')), m("ul", {
      className: "MastheadGames-list"
    }, games.map(game => m("li", {
      className: "MastheadGame",
      key: game.id
    }, m("span", {
      className: "MastheadGame-team"
    }, game.awayLogo ? m("img", {
      src: game.awayLogo,
      alt: "",
      loading: "lazy"
    }) : null, game.away), m("span", {
      className: "MastheadGame-when"
    }, kickoff(game)), m("span", {
      className: "MastheadGame-team"
    }, game.homeLogo ? m("img", {
      src: game.homeLogo,
      alt: "",
      loading: "lazy"
    }) : null, t('games.at', {
      team: game.home
    }))))), app.routes.picks ? m(Link, {
      className: "MastheadWidget-link",
      href: app.route('picks')
    }, t('games.cta')) : null);
  }
}
flarum.reg.add('ernestdefoe-masthead', 'forum/components/Games', Games);