import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import humanTime from 'flarum/common/helpers/humanTime';
import { t } from '../util';

/**
 * The forum's sections, from the tags the forum payload already carries.
 *
 * 🚨 No request and no query: flarum/tags sends every top-level tag the actor
 * may see, with its count and last activity, in the payload of every page.
 * Drawing from the store is what keeps this flat at 1 tag or 40.
 */
export function primaryTags() {
  return app.store.all('tags').filter(tag => tag.position() !== null && !tag.isChild() && !tag.isHidden()).sort((a, b) => a.position() - b.position());
}
export function tone(tag) {
  return tag.color() ? {
    '--mh-tag': tag.color()
  } : undefined;
}
export function tagHref(tag) {
  return app.route('tag', {
    tags: tag.slug()
  });
}
export function glyph(tag) {
  return m("span", {
    className: "MastheadTile-icon",
    "aria-hidden": "true"
  }, tag.icon() ? m(Icon, {
    name: tag.icon()
  }) : (tag.name() || '?').charAt(0));
}
export class TagGrid extends Component {
  view() {
    const tags = primaryTags();
    if (!tags.length) return null;
    return m("section", {
      className: "MastheadSection MastheadBrowse",
      "aria-labelledby": "masthead-browse"
    }, m("div", {
      className: "MastheadSection-head"
    }, m("h2", {
      id: "masthead-browse",
      className: "MastheadHeading"
    }, t('browse.title')), app.routes.tags ? m(Link, {
      className: "MastheadSection-more",
      href: app.route('tags')
    }, t('browse.all')) : null), m("div", {
      className: "MastheadTiles"
    }, tags.slice(0, this.attrs.limit).map(tag => {
      const last = tag.lastPostedAt();
      return m(Link, {
        className: "MastheadTile",
        href: tagHref(tag),
        style: tone(tag)
      }, glyph(tag), m("span", {
        className: "MastheadTile-text"
      }, m("span", {
        className: "MastheadTile-name"
      }, tag.name()), tag.description() ? m("span", {
        className: "MastheadTile-desc"
      }, tag.description()) : null, m("span", {
        className: "MastheadTile-meta"
      }, t('browse.count', {
        count: tag.discussionCount() || 0
      }), last ? [' · ', t('browse.latest', {
        time: humanTime(last)
      })] : null)));
    })));
  }
}

/** The phone's version: one scrolling row of chips. */
export class TagChips extends Component {
  view() {
    const tags = primaryTags();
    if (!tags.length) return null;
    return m("nav", {
      className: "MastheadChips",
      "aria-label": t('browse.title')
    }, tags.map(tag => m(Link, {
      className: "MastheadChip",
      href: tagHref(tag),
      style: tone(tag)
    }, tag.name())));
  }
}
flarum.reg.add('ernestdefoe-masthead', 'forum/components/TagGrid', { primaryTags: primaryTags,tone: tone,tagHref: tagHref,glyph: glyph,TagGrid: TagGrid,TagChips: TagChips, });